def semver_sort(versions):
    def parse(v):
        main = v.split('+', 1)[0]
        if '-' in main:
            core, pre = main.split('-', 1)
        else:
            core, pre = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if pre is None:
            has_pre = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_pre = 0
            ids = pre.split('.')
            pre_key = tuple(
                (0, int(i)) if i.isdigit() else (1, i)
                for i in ids
            )
        return (major, minor, patch, has_pre, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda p: (parse(p[1]), p[0]))
    return [v for _, v in indexed]

